def frame_check(frames, ports, max_frame):
    counts = {
        name: {"good": 0, "runt": 0, "giant": 0, "alignment": 0, "bad_fcs": 0}
        for name in ports
    }
    results = []
    for t, port, length, fcs, alignment in frames:
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        counts[port][cls] += 1
        results.append({"t": t, "port": port, "class": cls})
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "good": counts[name]["good"],
                "runt": counts[name]["runt"],
                "giant": counts[name]["giant"],
                "alignment": counts[name]["alignment"],
                "bad_fcs": counts[name]["bad_fcs"],
            }
            for name in ports
        ],
    }


FRAME_DECODE_FRAME_KEYS = frozenset({"t", "port", "data"})
FRAME_DECODE_DATA_RE = re.compile(r"[0-9a-f]+")
FRAME_DECODE_MIN_BYTES = 18
FRAME_DECODE_MIN_TAGGED_BYTES = 22
FRAME_DECODE_TAG = b"\x81\x00"


def validate_frame_decode_frames(frames, ports):
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    port_set = set(ports)
    result = []
    prev_t = None
    for frame in frames:
        if (
            not isinstance(frame, dict)
            or frozenset(frame) != FRAME_DECODE_FRAME_KEYS
        ):
            raise InvalidInput("bad frame")
        t = frame["t"]
        port = frame["port"]
        data = frame["data"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        if (
            not isinstance(data, str)
            or len(data) % 2 != 0
            or FRAME_DECODE_DATA_RE.fullmatch(data) is None
        ):
            raise InvalidInput("bad data")
        raw = bytes.fromhex(data)
        if len(raw) < FRAME_DECODE_MIN_BYTES:
            raise InvalidInput("frame too short")
        if raw[12:14] == FRAME_DECODE_TAG:
            # 单层 802.1Q：总长须容纳标签，且标签后不得再为 8100（双标签）
            if len(raw) < FRAME_DECODE_MIN_TAGGED_BYTES:
                raise InvalidInput("tagged frame too short")
            if raw[16:18] == FRAME_DECODE_TAG:
                raise InvalidInput("double tag")
        result.append((t, port, raw))
    return result


def _format_mac(octets):
    return ":".join("%02x" % byte for byte in octets)


def frame_decode(frames, max_frame):
    results = []
    for t, port, raw in frames:
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            priority = tci >> 13
            dei = (tci >> 12) & 1
            vlan = tci & 0x0FFF
            ethertype_offset = 16
        else:
            priority = None
            dei = None
            vlan = None
            ethertype_offset = 12
        ethertype = (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        body = raw[:-4]
        payload = raw[ethertype_offset + 2 : -4].hex()
        fcs = raw[-4:].hex()
        if len(raw) < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif len(raw) > max_frame:
            cls = "giant"
        elif raw[-4:] != (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little"):
            cls = "bad_fcs"
        else:
            cls = "good"
        results.append(
            {
                "t": t,
                "port": port,
                "class": cls,
                "dst": dst,
                "src": src,
                "vlan": vlan,
                "priority": priority,
                "dei": dei,
                "ethertype": ethertype,
                "payload": payload,
                "fcs": fcs,
            }
        )
    return {"results": results}


FRAME_ENCODE_FRAME_KEYS = frozenset(
    {"t", "port", "dst", "src", "vlan", "priority", "dei", "ethertype", "payload"}
)
FRAME_ENCODE_DATA_RE = re.compile(r"[0-9a-f]*")
FRAME_ENCODE_MIN_BODY = 60
FRAME_ENCODE_TAG_ETHERTYPE = 0x8100


def validate_frame_encode_frames(frames, ports):
    # t/port 沿用 frame-decode；dst/src 的 MAC 准入沿用 forward-decode
    # （dst 非零可组播/广播，src 须非零单播）
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    port_set = set(ports)
    result = []
    prev_t = None
    for frame in frames:
        if (
            not isinstance(frame, dict)
            or frozenset(frame) != FRAME_ENCODE_FRAME_KEYS
        ):
            raise InvalidInput("bad frame")
        t = frame["t"]
        port = frame["port"]
        dst = frame["dst"]
        src = frame["src"]
        vlan = frame["vlan"]
        priority = frame["priority"]
        dei = frame["dei"]
        ethertype = frame["ethertype"]
        payload = frame["payload"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        if not valid_dst_mac(dst):
            raise InvalidInput("bad dst")
        if not valid_mac(src):
            raise InvalidInput("bad src")
        if vlan is not None and (not _is_int(vlan) or not 1 <= vlan <= 4094):
            raise InvalidInput("bad vlan")
        if not _is_int(priority) or not 0 <= priority <= 7:
            raise InvalidInput("bad priority")
        if not isinstance(dei, bool):
            raise InvalidInput("bad dei")
        if vlan is None and (priority != 0 or dei):
            # 无标签帧不带 PCP/DEI：priority=0 且 dei=false
            raise InvalidInput("priority/dei require tag")
        if (
            not _is_int(ethertype)
            or not 0 <= ethertype <= 0xFFFF
            or ethertype == FRAME_ENCODE_TAG_ETHERTYPE
        ):
            raise InvalidInput("bad ethertype")
        if payload is None:
            payload_bytes = b""
        elif (
            not isinstance(payload, str)
            or len(payload) % 2 != 0
            or FRAME_ENCODE_DATA_RE.fullmatch(payload) is None
        ):
            raise InvalidInput("bad payload")
        else:
            payload_bytes = bytes.fromhex(payload)
        result.append(
            (t, port, dst, src, vlan, priority, dei, ethertype, payload_bytes)
        )
    return result


def _mac_bytes(mac):
    return bytes(int(part, 16) for part in mac.split(":"))


def frame_encode(frames, max_frame):
    results = []
    for t, port, dst, src, vlan, priority, dei, ethertype, payload in frames:
        body = _mac_bytes(dst) + _mac_bytes(src)
        if vlan is not None:
            tci = (priority << 13) | (int(dei) << 12) | vlan
            body += FRAME_DECODE_TAG + tci.to_bytes(2, "big")
        body += ethertype.to_bytes(2, "big") + payload
        # payload 后补零，使正文（不含 FCS）至少 60 字节
        if len(body) < FRAME_ENCODE_MIN_BODY:
            body += b"\x00" * (FRAME_ENCODE_MIN_BODY - len(body))
        # 正文无符号 crc32 的 4 字节小端值作为 FCS
        raw = body + (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little")
        if len(raw) > max_frame:
            raise InvalidInput("frame too long")
        results.append(
            {"t": t, "port": port, "length": len(raw), "data": raw.hex()}
        )
    return {"results": results}


